import{_ as A,c as p,a2 as t,o as s}from"./chunks/framework.CqbvlPrP.js";const a="/assets/img/stock/%E4%BA%A4%E6%98%93%E8%AE%A4%E7%9F%A5/%E4%BA%A4%E6%98%93%E6%98%AF%E6%90%9E%E5%BA%94%E5%AF%B9%E8%80%8C%E4%B8%8D%E6%98%AF%E6%90%9E%E9%A2%84%E6%B5%8B/1.jpg",B="/assets/img/stock/%E4%BA%A4%E6%98%93%E8%AE%A4%E7%9F%A5/%E4%BA%A4%E6%98%93%E6%98%AF%E6%90%9E%E5%BA%94%E5%AF%B9%E8%80%8C%E4%B8%8D%E6%98%AF%E6%90%9E%E9%A2%84%E6%B5%8B/2.jpg",o="/assets/img/stock/%E4%BA%A4%E6%98%93%E8%AE%A4%E7%9F%A5/%E4%BA%A4%E6%98%93%E6%98%AF%E6%90%9E%E5%BA%94%E5%AF%B9%E8%80%8C%E4%B8%8D%E6%98%AF%E6%90%9E%E9%A2%84%E6%B5%8B/3.jpg",c="/assets/img/stock/%E4%BA%A4%E6%98%93%E8%AE%A4%E7%9F%A5/%E4%BA%A4%E6%98%93%E6%98%AF%E6%90%9E%E5%BA%94%E5%AF%B9%E8%80%8C%E4%B8%8D%E6%98%AF%E6%90%9E%E9%A2%84%E6%B5%8B/4.jpg",e="/assets/img/stock/%E4%BA%A4%E6%98%93%E8%AE%A4%E7%9F%A5/%E4%BA%A4%E6%98%93%E6%98%AF%E6%90%9E%E5%BA%94%E5%AF%B9%E8%80%8C%E4%B8%8D%E6%98%AF%E6%90%9E%E9%A2%84%E6%B5%8B/5.jpg",r="/assets/img/stock/%E4%BA%A4%E6%98%93%E8%AE%A4%E7%9F%A5/%E4%BA%A4%E6%98%93%E6%98%AF%E6%90%9E%E5%BA%94%E5%AF%B9%E8%80%8C%E4%B8%8D%E6%98%AF%E6%90%9E%E9%A2%84%E6%B5%8B/6.jpg",k=JSON.parse('{"title":"为什么说交易系统越简单越好？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/不预测/交易是搞应对而不是搞预测.md","filePath":"stock/不预测/交易是搞应对而不是搞预测.md"}'),i={name:"stock/不预测/交易是搞应对而不是搞预测.md"};function _(m,E,n,F,g,l){return s(),p("div",null,E[0]||(E[0]=[t('<h1 id="为什么说交易系统越简单越好" tabindex="-1">为什么说交易系统越简单越好？ <a class="header-anchor" href="#为什么说交易系统越简单越好" aria-label="Permalink to &quot;为什么说交易系统越简单越好？&quot;">​</a></h1><p>因为交易是搞应对而不是搞预测。</p><p>如果我俩猜拳，在不考虑规则的情况下，怎么样你才能赢的最简单，那就是你比我慢一步，我出拳头，你就出布，我出布，你就出剪刀。那怎么样你才会赢的最艰难呢，那就是你比我快一拍，你先出我后出，这时候你不得不去预测我会出什么，但事实是你永远先出，所以你大概率会输。</p><p>对于猜拳来说，规则已经定死了，所以你先出和后出都是不可以的。但是对于交易来说，没人拿刀逼着你先出牌，所以，交易怎么样赢的最轻松，你让市场先出牌，不要去猜测市场会怎么，市场走出来什么样就是什么样，你等他走出来之后再动手，不就简单了么。</p><p>为啥有些人会把交易系统搞得很复杂呢，原因是他们总想预测市场，总想先于市场一步，但是他们忘记了一点，市场并不是你一个人在交易，你认为的好不叫好，大家都认为的好才叫好。墙倒众人推，做交易，不是要你去找一个墙去推推看他会不会倒，而是要去找一个已经快要被大家推倒的墙你跟着大家一块推。交易又叫投机，投机就是耍滑头，那就好好的把滑头耍好就行了。</p><p>我来举一个具体的例子，看下面的图1:</p><p><img src="'+a+'" alt="图1"></p><p>市场经历了一波下跌，然后构成了这样的图形，市场在干嘛，说实话我不知道他在干嘛，胡乱洗。</p><p>这时候，你说我知道，他是三角收敛形态，嗯，跌了这么多了，至少有个反弹，现在低点一步一步抬高，而且在创局部新高，macd金叉，短期均线也拐头了，我要在三角形边上做多，然后他就变成了这样，你亏了。</p><p><img src="'+B+'" alt="图2"></p><p>第一笔亏了 这时候你说这下我知道了，双底结构，这里是支撑，主力真坏，回踩60日均线，他一定会反弹的，别想骗我，继续做多，然后他又变成了这样，你又亏了。</p><p><img src="'+o+'" alt="图3"></p><p>第一笔亏了</p><p>又亏了 这时候，你认怂了，你说，他还是要跌，我还是做空吧，前面两单我都逆势交易了，大势是空头，顺势而为总没错吧，空单下去，然后市场又变成这样了，你心态炸了。</p><p><img src="'+c+'" alt="图4"></p><p>心态炸了</p><p>实际上，真正的交易系统根本不需要预测市场，只需要应对就好了，第一幅图，收敛结构突破哪边做哪边，如下图</p><p><img src="'+e+'" alt="图5"></p><p>突破那边做那边 第二幅图，盘整结构，突破哪边做哪边，假突破怎么办，假突破你就做假突破，你做空亏了一次，现在假突破你再做多赚回来就好了，或者你不想被假突破，那就去做回踩。</p><p><img src="'+r+'" alt="图6"></p><p>市场要随机应变 所以，一旦起了先于市场出牌的念头，交易就会变得无比的复杂，你会不停的去找各种因素，一个技术指标叠加一个技术指标，这样优化又那样优化，最后发现还是不行，因为市场本来就不可以被预测，你在尝试解决一个不可能的事情，你说答案会有多复杂呢？</p><p>交易系统要的是应对之策，如果市场出a，我就出b，如果市场出c，我就出d，如果市场耍赖，他出了a然后他又偷牌把a撤了换成c，那我也耍赖，我偷牌也把b撤了换成d。交易者在市场中就要像水一样，市场是瓶子，交易者就变成瓶子，市场是袋子，交易者就变成袋子，永远跟进市场，紧贴市场，而非预测市场，强迫市场。</p><p>这样，你的交易系统自然就简单了下来。</p>',23)]))}const f=A(i,[["render",_]]);export{k as __pageData,f as default};
